<script setup>
import { ref, computed, watch } from 'vue'
import { LayoutDashboard, Calculator, Layers3, Printer, Settings2, Plus, Trash2, ExternalLink, Download, Upload, Box, Zap, Clock3, TrendingUp, PoundSterling, ChevronRight, Info, Check, X } from 'lucide-vue-next'
const KEY = 'printquote-v1'
const initial = { settings:{currency:'GBP',energyRate:0.28,labourRate:12,defaultMargin:30}, filaments:[{id:'f1',name:'PLA Basic',brand:'Generic',material:'PLA',colour:'Slate Grey',price:18.99,url:''},{id:'f2',name:'PETG',brand:'Generic',material:'PETG',colour:'Black',price:22.5,url:''},{id:'f3',name:'TPU Flexible',brand:'Generic',material:'TPU',colour:'Black',price:29.99,url:''}], printers:[{id:'p1',name:'Bambu Lab A1',technology:'FDM',power:95,setupMinutes:10,postMinutes:10,overheadRate:0.25},{id:'p2',name:'Prusa MK4',technology:'FDM',power:110,setupMinutes:10,postMinutes:15,overheadRate:0.35}], quotes:[] }
function clone(x){return JSON.parse(JSON.stringify(x))}
function load(){try {const s=JSON.parse(localStorage.getItem(KEY)); if(s && Array.isArray(s.filaments) && Array.isArray(s.printers)) return {...clone(initial),...s,settings:{...initial.settings,...s.settings}}}catch{}return clone(initial)}
const state=ref(load())
watch(state,v=>localStorage.setItem(KEY,JSON.stringify(v)),{deep:true})
const page=ref('calculator'), mobileMenu=ref(false), notification=ref('')
function toast(t){notification.value=t;setTimeout(()=>notification.value='',3000)}
const uid=()=>Math.random().toString(36).slice(2,10)
const money=v=>new Intl.NumberFormat('en-GB',{style:'currency',currency:state.value.settings.currency||'GBP'}).format(Number(v)||0)
const num=(v)=>Math.max(0,Number(v)||0)
const quote=ref({name:'',filamentId:'f1',printerId:'p1',grams:120,hours:4,minutes:30,quantity:1,margin:30,extraCost:0,setupOverride:false})
const filament=computed(()=>state.value.filaments.find(f=>f.id===quote.value.filamentId))
const printer=computed(()=>state.value.printers.find(p=>p.id===quote.value.printerId))
const calc=computed(()=>{const q=quote.value,p=printer.value;const qty=Math.max(1,Math.floor(Number(q.quantity)||1));const hours=num(q.hours)+num(q.minutes)/60;const material=num(q.grams)/1000*num(filament.value?.price)*qty;const energy=hours*num(p?.power)/1000*num(state.value.settings.energyRate)*qty;const labour=(num(p?.setupMinutes)+num(p?.postMinutes)*qty)/60*num(state.value.settings.labourRate);const overhead=hours*num(p?.overheadRate)*qty;const extras=num(q.extraCost)*qty;const cost=material+energy+labour+overhead+extras;const margin=Math.min(99.9,num(q.margin));const price=cost/(1-margin/100);const profit=price-cost;return {qty,hours,material,energy,labour,overhead,extras,cost,price,profit,margin,markup:cost?profit/cost*100:0,unit:price/qty}})
const editingFilament=ref(null),editingPrinter=ref(null)
function newFilament(){editingFilament.value={id:uid(),name:'',brand:'',material:'PLA',colour:'',price:20,url:''}}
function editFilament(f){editingFilament.value=clone(f)}
function saveFilament(){const f=editingFilament.value;if(!f.name.trim()){toast('Please enter a filament name');return}if(f.url && !/^https?:\/\//i.test(f.url)){toast('Purchase link must start with http:// or https://');return}f.price=num(f.price);const idx=state.value.filaments.findIndex(x=>x.id===f.id);if(idx<0)state.value.filaments.push(f);else state.value.filaments[idx]=f;if(!quote.value.filamentId)quote.value.filamentId=f.id;editingFilament.value=null;toast('Filament saved')}
function removeFilament(id){if(!confirm('Delete this filament?'))return;state.value.filaments=state.value.filaments.filter(f=>f.id!==id);if(quote.value.filamentId===id)quote.value.filamentId=state.value.filaments[0]?.id||''}
function newPrinter(){editingPrinter.value={id:uid(),name:'',technology:'FDM',power:100,setupMinutes:10,postMinutes:10,overheadRate:0.25}}
function editPrinter(p){editingPrinter.value=clone(p)}
function savePrinter(){const p=editingPrinter.value;if(!p.name.trim()){toast('Please enter a printer name');return}for(const k of ['power','setupMinutes','postMinutes','overheadRate'])p[k]=num(p[k]);const idx=state.value.printers.findIndex(x=>x.id===p.id);if(idx<0)state.value.printers.push(p);else state.value.printers[idx]=p;if(!quote.value.printerId)quote.value.printerId=p.id;editingPrinter.value=null;toast('Printer saved')}
function removePrinter(id){if(!confirm('Delete this printer profile?'))return;state.value.printers=state.value.printers.filter(p=>p.id!==id);if(quote.value.printerId===id)quote.value.printerId=state.value.printers[0]?.id||''}
function saveQuote(){if(!filament.value||!printer.value){toast('Add a filament and printer first');return}state.value.quotes.unshift({id:uid(),name:quote.value.name.trim()||'Untitled print',date:new Date().toISOString(),filament:filament.value.name,printer:printer.value.name,details:clone(quote.value),result:clone(calc.value)});toast('Quote saved to history')}
function loadQuote(q){quote.value={...quote.value,...clone(q.details)};page.value='calculator';toast('Quote loaded')}
function removeQuote(id){state.value.quotes=state.value.quotes.filter(q=>q.id!==id)}
function exportData(){const blob=new Blob([JSON.stringify(state.value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='printquote-backup.json';a.click();URL.revokeObjectURL(url);toast('Backup downloaded')}
const fileInput=ref(null)
async function importData(e){const f=e.target.files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!Array.isArray(data.filaments)||!Array.isArray(data.printers)||!data.settings)throw Error('Invalid backup');if(!confirm('Replace your current data with this backup?'))return;state.value={...clone(initial),...data};quote.value.filamentId=state.value.filaments[0]?.id||'';quote.value.printerId=state.value.printers[0]?.id||'';toast('Backup restored')}catch{toast('Could not read backup file')}finally{e.target.value=''}}
const nav=[{id:'calculator',label:'Cost calculator',icon:Calculator},{id:'filaments',label:'Filament library',icon:Layers3},{id:'printers',label:'Printer profiles',icon:Printer},{id:'history',label:'Saved quotes',icon:LayoutDashboard},{id:'settings',label:'Settings',icon:Settings2}]
function navigate(id){page.value=id;mobileMenu.value=false}
const pageTitle=computed(()=>nav.find(n=>n.id===page.value)?.label||'Calculator')
</script>

<template>
<div class="shell">
  <aside class="sidebar" :class="{open:mobileMenu}">
    <div class="brand"><div class="brand-icon"><Box :size="23" :stroke-width="2.5"/></div><div><strong>PrintQuote<span>.</span></strong><small>3D PRINT COSTING</small></div></div>
    <div class="side-label">WORKSPACE</div>
    <nav><button v-for="n in nav" :key="n.id" :class="['nav-link',{active:page===n.id}]" @click="navigate(n.id)"><component :is="n.icon" :size="18"/><span>{{n.label}}</span><ChevronRight class="chev" :size="15"/></button></nav>
    <div class="side-bottom"><div class="status-dot"></div><div><strong>Local workspace</strong><small>Saved in this browser</small></div></div>
  </aside>
  <div v-if="mobileMenu" class="mobile-overlay" @click="mobileMenu=false"></div>
  <main class="main">
    <header class="topbar"><button class="mobile-toggle" @click="mobileMenu=!mobileMenu">☰</button><div class="breadcrumb">Workspace <ChevronRight :size="14"/> <b>{{pageTitle}}</b></div><div class="top-right"><span class="top-pill"><span class="status-dot"></span> All changes saved</span><div class="avatar">PQ</div></div></header>
    <div class="content">
      <div v-if="page==='calculator'">
        <div class="page-head"><div><div class="eyebrow">ESTIMATE & QUOTE</div><h1>Print cost calculator</h1><p>Know your costs. Price every print with confidence.</p></div><button class="btn primary" @click="saveQuote"><Plus :size="17"/> Save quote</button></div>
        <div class="stats-grid">
          <div class="stat"><div class="stat-top"><span>Total production cost</span><div class="mini-icon violet"><PoundSterling :size="17"/></div></div><div class="stat-value">{{money(calc.cost)}}</div><small>All costs included</small></div>
          <div class="stat"><div class="stat-top"><span>Suggested selling price</span><div class="mini-icon blue"><Calculator :size="17"/></div></div><div class="stat-value">{{money(calc.price)}}</div><small>{{calc.margin}}% profit margin</small></div>
          <div class="stat"><div class="stat-top"><span>Estimated profit</span><div class="mini-icon green"><TrendingUp :size="17"/></div></div><div class="stat-value profit">{{money(calc.profit)}}</div><small>{{money(calc.unit)}} per item selling price</small></div>
        </div>
        <div class="two-col">
          <section class="card"><div class="card-heading"><div><h2>Print details</h2><p>Enter your slicer estimates and select materials.</p></div><div class="card-badge">01 / INPUT</div></div>
            <div class="field"><label>Project name <span>Optional</span></label><input v-model="quote.name" placeholder="e.g. Custom phone stand"/></div>
            <div class="field-grid"><div class="field"><label>Printer model</label><select v-model="quote.printerId"><option disabled value="">Select printer</option><option v-for="p in state.printers" :value="p.id" :key="p.id">{{p.name}}</option></select></div><div class="field"><label>Filament</label><select v-model="quote.filamentId"><option disabled value="">Select filament</option><option v-for="f in state.filaments" :value="f.id" :key="f.id">{{f.brand ? f.brand+' · ' : ''}}{{f.name}}</option></select></div></div>
            <div class="field-grid"><div class="field"><label>Filament used <span>grams / item</span></label><div class="input-unit"><input type="number" min="0" step="0.1" v-model.number="quote.grams"/><span>g</span></div></div><div class="field"><label>Quantity</label><div class="input-unit"><input type="number" min="1" step="1" v-model.number="quote.quantity"/><span>pcs</span></div></div></div>
            <div class="field"><label>Print duration <span>per item</span></label><div class="field-grid"><div class="input-unit"><input type="number" min="0" step="1" v-model.number="quote.hours"/><span>hours</span></div><div class="input-unit"><input type="number" min="0" max="59" step="1" v-model.number="quote.minutes"/><span>min</span></div></div></div>
            <div class="field-grid"><div class="field"><label>Target profit margin</label><div class="input-unit"><input type="number" min="0" max="99.9" step="1" v-model.number="quote.margin"/><span>%</span></div></div><div class="field"><label>Extra cost <span>per item</span></label><div class="input-unit"><input type="number" min="0" step="0.01" v-model.number="quote.extraCost"/><span>{{state.settings.currency==='GBP'?'£':state.settings.currency==='USD'?'$':'€'}}</span></div></div></div>
            <div class="info-box"><Info :size="17"/><span>Printer setup, post-processing, power consumption and machine overhead are pulled automatically from your printer profile.</span></div>
          </section>
          <section class="card result-card"><div class="card-heading"><div><h2>Cost breakdown</h2><p>A clear view of where every penny goes.</p></div><div class="card-badge">02 / RESULTS</div></div>
            <div class="breakdown"><div class="cost-row"><div><span class="cost-icon"><Layers3 :size="16"/></span>Filament <small>{{num(quote.grams)*calc.qty}}g total</small></div><strong>{{money(calc.material)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Zap :size="16"/></span>Electricity <small>{{printer?.power||0}} W</small></div><strong>{{money(calc.energy)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Clock3 :size="16"/></span>Labour <small>Setup + finishing</small></div><strong>{{money(calc.labour)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Printer :size="16"/></span>Machine overhead <small>Wear & maintenance</small></div><strong>{{money(calc.overhead)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Plus :size="16"/></span>Additional costs</div><strong>{{money(calc.extras)}}</strong></div></div>
            <div class="totals"><div><span>Production cost</span><strong>{{money(calc.cost)}}</strong></div><div><span>Profit ({{calc.margin}}% margin)</span><strong class="profit">+ {{money(calc.profit)}}</strong></div></div>
            <div class="grand-total"><div><span>RECOMMENDED SELLING PRICE</span><strong>{{money(calc.price)}}</strong><small>{{money(calc.unit)}} per item · {{calc.qty}} item{{calc.qty===1?'':'s'}}</small></div><TrendingUp :size="29"/></div>
            <p class="footnote">Profit margin = profit ÷ selling price. This differs from markup, which is profit ÷ cost. Prices exclude VAT and payment/platform fees unless added as extra costs.</p>
          </section>
        </div>
      </div>
      <div v-if="page==='filaments'"><div class="page-head"><div><div class="eyebrow">MATERIALS</div><h1>Filament library</h1><p>Keep your materials, cost per kilogram and supplier links in one place.</p></div><button class="btn primary" @click="newFilament"><Plus :size="17"/> Add filament</button></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>FILAMENT</th><th>MATERIAL</th><th>COLOUR</th><th>PRICE / KG</th><th>SUPPLIER</th><th></th></tr></thead><tbody><tr v-for="f in state.filaments" :key="f.id"><td><strong>{{f.name}}</strong><small>{{f.brand||'Unbranded'}}</small></td><td><span class="tag">{{f.material}}</span></td><td>{{f.colour||'—'}}</td><td class="bold">{{money(f.price)}}</td><td><a v-if="f.url" :href="f.url" target="_blank" rel="noopener noreferrer" class="link">Buy filament <ExternalLink :size="13"/></a><span v-else class="muted">Not set</span></td><td class="actions"><button class="btn small" @click="editFilament(f)">Edit</button><button class="icon-button danger" title="Delete" @click="removeFilament(f.id)"><Trash2 :size="16"/></button></td></tr><tr v-if="!state.filaments.length"><td colspan="6" class="empty">No filaments yet. Add your first material to get started.</td></tr></tbody></table></div></div><div class="info-box page-info"><Info :size="17"/>This is a pricing library, not inventory tracking. Filament quantities and stock levels are intentionally not tracked.</div></div>
      <div v-if="page==='printers'"><div class="page-head"><div><div class="eyebrow">EQUIPMENT</div><h1>Printer profiles</h1><p>Configure a cost profile for every printer model you use.</p></div><button class="btn primary" @click="newPrinter"><Plus :size="17"/> Add printer</button></div><div class="printer-grid"><div v-for="p in state.printers" :key="p.id" class="card printer-card"><div class="printer-top"><div class="printer-illustration"><Printer :size="27"/></div><span class="tag">{{p.technology}}</span></div><h2>{{p.name}}</h2><div class="printer-details"><div><span>Average power</span><strong>{{p.power}} W</strong></div><div><span>Setup time / job</span><strong>{{p.setupMinutes}} min</strong></div><div><span>Post-processing / item</span><strong>{{p.postMinutes}} min</strong></div><div><span>Machine overhead / hr</span><strong>{{money(p.overheadRate)}}</strong></div></div><div class="printer-actions"><button class="btn small" @click="editPrinter(p)">Edit profile</button><button class="icon-button danger" @click="removePrinter(p.id)"><Trash2 :size="16"/></button></div></div><button class="add-card" @click="newPrinter"><Plus :size="26"/><strong>Add printer profile</strong><span>Set up another machine</span></button></div></div>
      <div v-if="page==='history'"><div class="page-head"><div><div class="eyebrow">YOUR PROJECTS</div><h1>Saved quotes</h1><p>Review past estimates and reuse them for your next print.</p></div></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>PROJECT</th><th>DATE</th><th>PRINTER</th><th>PRODUCTION COST</th><th>SELLING PRICE</th><th>PROFIT</th><th></th></tr></thead><tbody><tr v-for="q in state.quotes" :key="q.id"><td><strong>{{q.name}}</strong><small>{{q.filament}}</small></td><td>{{new Date(q.date).toLocaleDateString('en-GB')}}</td><td>{{q.printer}}</td><td>{{money(q.result.cost)}}</td><td class="bold">{{money(q.result.price)}}</td><td class="profit bold">{{money(q.result.profit)}}</td><td class="actions"><button class="btn small" @click="loadQuote(q)">Load</button><button class="icon-button danger" @click="removeQuote(q.id)"><Trash2 :size="16"/></button></td></tr><tr v-if="!state.quotes.length"><td colspan="7" class="empty">No saved quotes yet. Create an estimate and click “Save quote”.</td></tr></tbody></table></div></div></div>
      <div v-if="page==='settings'"><div class="page-head"><div><div class="eyebrow">PREFERENCES</div><h1>Settings</h1><p>Set the rates used across all your cost estimates.</p></div></div><div class="settings-layout"><section class="card"><div class="card-heading"><div><h2>Business rates</h2><p>Changes are saved automatically.</p></div><Settings2 :size="21" class="muted"/></div><div class="field"><label>Currency</label><select v-model="state.settings.currency"><option value="GBP">British Pound (£)</option><option value="EUR">Euro (€)</option><option value="USD">US Dollar ($)</option></select></div><div class="field"><label>Electricity price <span>per kWh</span></label><div class="input-unit"><input type="number" min="0" step="0.001" v-model.number="state.settings.energyRate"/><span>/ kWh</span></div></div><div class="field"><label>Labour rate <span>per hour</span></label><div class="input-unit"><input type="number" min="0" step="0.5" v-model.number="state.settings.labourRate"/><span>/ hr</span></div></div><div class="field"><label>Default margin <span>for new estimates</span></label><div class="input-unit"><input type="number" min="0" max="99.9" step="1" v-model.number="state.settings.defaultMargin" @change="quote.margin=state.settings.defaultMargin"/><span>%</span></div></div><div class="info-box"><Info :size="17"/>Electricity is calculated from average printer wattage × print duration × your kWh rate. Labour uses the setup and finishing times saved in each printer profile.</div></section><section class="card"><div class="card-heading"><div><h2>Your data</h2><p>Export or restore your local workspace.</p></div><Download :size="21" class="muted"/></div><p class="secondary-text">All filaments, printers, settings and saved quotes are stored locally in this browser. Export a JSON backup to move them to another device or browser.</p><div class="backup-actions"><button class="btn" @click="exportData"><Download :size="16"/> Export backup</button><button class="btn" @click="fileInput?.click()"><Upload :size="16"/> Import backup</button><input ref="fileInput" type="file" accept="application/json,.json" hidden @change="importData"/></div><div class="info-box"><Info :size="17"/>Clearing browser site data removes local records unless you've exported a backup. There is no server-side database in this version.</div></section></div></div>
      <footer>PrintQuote <span>•</span> Built for makers, designed for clear pricing.</footer>
    </div>
  </main>
  <div v-if="notification" class="toast"><Check :size="17"/>{{notification}}</div>
  <div v-if="editingFilament" class="modal-backdrop" @click.self="editingFilament=null"><form class="modal" @submit.prevent="saveFilament"><div class="modal-head"><div><h2>{{state.filaments.some(f=>f.id===editingFilament.id)?'Edit filament':'Add filament'}}</h2><p>Material pricing details</p></div><button type="button" class="icon-button" @click="editingFilament=null"><X :size="20"/></button></div><div class="field-grid"><div class="field"><label>Filament name *</label><input v-model="editingFilament.name" required placeholder="e.g. PLA Matte"/></div><div class="field"><label>Brand</label><input v-model="editingFilament.brand" placeholder="e.g. eSUN"/></div></div><div class="field-grid"><div class="field"><label>Material type</label><select v-model="editingFilament.material"><option v-for="m in ['PLA','PLA+','PETG','ABS','ASA','TPU','Nylon','PC','Other']" :key="m">{{m}}</option></select></div><div class="field"><label>Colour / variant</label><input v-model="editingFilament.colour" placeholder="e.g. Matte black"/></div></div><div class="field"><label>Price per kilogram</label><input type="number" min="0" step="0.01" v-model.number="editingFilament.price"/></div><div class="field"><label>Purchase link</label><input type="url" v-model="editingFilament.url" placeholder="https://..."/></div><div class="modal-actions"><button type="button" class="btn" @click="editingFilament=null">Cancel</button><button class="btn primary" type="submit">Save filament</button></div></form></div>
  <div v-if="editingPrinter" class="modal-backdrop" @click.self="editingPrinter=null"><form class="modal" @submit.prevent="savePrinter"><div class="modal-head"><div><h2>{{state.printers.some(p=>p.id===editingPrinter.id)?'Edit printer':'Add printer'}}</h2><p>Printer-specific cost profile</p></div><button type="button" class="icon-button" @click="editingPrinter=null"><X :size="20"/></button></div><div class="field"><label>Printer model *</label><input v-model="editingPrinter.name" required placeholder="e.g. Bambu Lab P1S"/></div><div class="field-grid"><div class="field"><label>Technology</label><select v-model="editingPrinter.technology"><option>FDM</option><option>Resin</option><option>Other</option></select></div><div class="field"><label>Average power consumption (W)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.power"/></div></div><div class="field-grid"><div class="field"><label>Setup time / job (min)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.setupMinutes"/></div><div class="field"><label>Post-processing / item (min)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.postMinutes"/></div></div><div class="field"><label>Machine overhead / print hour</label><input type="number" min="0" step="0.01" v-model.number="editingPrinter.overheadRate"/></div><div class="info-box"><Info :size="17"/>Machine overhead can account for wear, depreciation, servicing and consumables. Enter your own hourly estimate.</div><div class="modal-actions"><button type="button" class="btn" @click="editingPrinter=null">Cancel</button><button class="btn primary" type="submit">Save printer</button></div></form></div>
</div>
</template>
